# Completa la línea marcada y compruébala con py check.
def fragiles(matriz, activos):
    # matriz: {ataque: [controles que lo bloquean]}
    salida = []
    for ataque, bloquean in matriz.items():
        usados = [c for c in bloquean if c in activos]
        salida.append(ataque)   # ← cambia esta línea: solo si lo para exactamente un control activo
    return sorted(salida)

